class Solution {
public:
    int minConnectedGroups(vector<vector<int>>& intervals,int k) {
        sort(intervals.begin(),intervals.end());
        vector<pair<int,int>> merged;
        for (auto& v:intervals) {
            if (merged.empty() || v[0]>merged.back().second)
                merged.push_back({v[0],v[1]});
            else merged.back().second=max(merged.back().second,v[1]);
        }
        int m=merged.size(), best=0, right=0;
        for (int left=0;left<m;++left) {
            right=max(right,left);
            while (right+1<m && merged[right+1].first-merged[left].second<=k)
                ++right;
            best=max(best,right-left);
        }
        return m-best;
    }
};
